import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 95 · Everyday recipe: shepherd's pie (cottage pie)

sc("""Sweetheart, shepherd's pie is the most comforting supper in the world. A rich, meaty filling in thick gravy, under a fluffy blanket of mashed potatoes with a golden, crispy top. But most of the ones I've eaten are soupy underneath, with the potatoes sinking into a puddle, or dry and bland like cafeteria food. And it's always the same five mistakes. Every one is easy to fix.""",
   "soupy shepherd's pie potatoes sinking", "A SOUPY PUDDLE")
sc("""So tonight I'm giving you my mother's shepherd's pie, step by step, the Monday supper that used up Sunday's leftovers on Elm Street. And stay with me, because the last secret is what she did to the top of the potatoes with a plain dinner fork, and it's why the crust was so crispy that Danny and I fought over the corners.""",
   "golden shepherd's pie crispy potato top", "WE FOUGHT OVER THE CORNERS")

ch("Monday supper")
sc("""In our house, Sunday was roast day, and Monday was shepherd's pie day. My mother took whatever was left of Sunday's pot roast or roast beef, chopped it up fine, mixed it with the leftover gravy and vegetables, and covered it with the leftover mashed potatoes. Nothing was ever wasted in her kitchen, honey. Sunday dinner fed us twice. That was the whole point of it.""",
   "leftover pot roast on Sunday platter", "SUNDAY FED US TWICE")
sc("""It came from the farmhouses of England and Ireland, where poor families did the same thing with leftover mutton, two hundred years ago. When it was made with lamb, they called it shepherd's pie, because shepherds tend sheep. When it was made with beef, it was cottage pie. In America, nearly everybody makes it with ground beef, and calls it shepherd's pie anyway. In a minute I'll tell you which one I make.""",
   "old English farmhouse kitchen hearth", "SHEPHERD'S OR COTTAGE?")
sc("""My father loved it so much that when my mother asked him what he wanted for his fiftieth birthday dinner, he said, shepherd's pie, Dorothy. She said, Walter, I was going to make a standing rib roast. And he said, then make the roast on Sunday, and the pie on Monday, and I'll have two birthdays. And that's exactly what she did.""",
   "birthday dinner 1960s family table", "TWO BIRTHDAYS")

ch("What you need")
sc("""Here's what you need for a nine by thirteen pan. For the filling, one and a half pounds of ground beef or ground lamb. One onion, two carrots, two stalks of celery, all chopped small. Two cloves of garlic. Two tablespoons of tomato paste and two tablespoons of flour. One cup of beef broth, a tablespoon of Worcestershire sauce, some thyme, and a cup of frozen peas.""",
   "ground beef onions carrots peas ingredients", "THE FILLING")
sc("""For the top, two and a half pounds of russet potatoes, half a stick of butter, half a cup of warm milk, salt and pepper, and one egg yolk, which is my mother's trick for a golden top. And a handful of sharp cheddar, if you like it, which my father did. Russets, honey, not red potatoes. Russets mash up light and fluffy. Red potatoes turn gluey.""",
   "russet potatoes butter milk egg", "THE TOP")

ch("The filling")
sc("""Brown the meat in a big skillet over medium-high heat, breaking it up with a spoon, until it's well browned, not gray. And here's mistake number one. Not draining the fat. If you leave all that grease in, it pools at the bottom of the pan and makes the whole pie greasy and the potatoes slide off. Tip the pan and spoon most of it out, leaving just a tablespoon or two.""",
   "browning ground beef in skillet", "DRAIN THE FAT")
sc("""Add the onion, carrots and celery, and cook them in the same pan for about eight minutes, until they're soft. Then the garlic and tomato paste, for two minutes, stirring, until the paste darkens. Sprinkle the flour over everything and stir it in. That flour is what thickens the gravy. Mistake number two is skipping it, and that's exactly how you get the soupy puddle underneath.""",
   "vegetables and tomato paste in skillet", "DON'T SKIP THE FLOUR")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. Pour in the broth and the Worcestershire sauce, add the thyme, and let it simmer for ten to fifteen minutes, until it's thick, like stew. Not soup. Drag a spoon across the bottom of the pan. If the gravy doesn't rush back in to fill the line right away, it's ready. Stir in the frozen peas.""",
   "thick meat filling simmering skillet", "THICK LIKE STEW")
sc("""And mistake number three. Putting hot potatoes on hot filling straight away. Let the filling cool for ten minutes first, in the baking dish. If it's bubbling hot, the potatoes sink right into it and disappear. A slightly cooled filling holds the potatoes up on top, like a lid. My mother made the filling first, then the potatoes, so it had time to settle.""",
   "meat filling cooling in baking dish", "LET IT COOL FIRST")

sc("""And here's a little trick from the nineteen fifties, honey, when meat was expensive. Stretch the filling with a cup of cooked lentils or a can of drained beans mixed in with the beef. It feeds two more people, nobody can tell, and it makes the filling heartier. My mother did that all through the lean years when my father's hours were cut, and my father never once noticed. Or if he did, he never said.""",
   "cooked lentils mixed into ground beef", "STRETCH IT")
ch("The potatoes")
sc("""Peel and cut the potatoes into even chunks, put them in a pot of cold salted water, and bring it to a boil. Cook about fifteen minutes, until a fork slides right through. Drain them well, then put them back in the hot pot over low heat for one minute, shaking it, to steam off the last of the water. Wet potatoes make a soggy top, honey.""",
   "drained potatoes steaming in pot", "STEAM THEM DRY")
sc("""Mash them with the butter, warm milk, salt and pepper. And here's mistake number four. Making them too soft. For shepherd's pie, you want the potatoes a little stiffer than you'd serve them on a plate. Soft, runny potatoes melt into the filling. Then beat in that egg yolk. It makes them richer and helps them turn golden in the oven. Mother's trick.""",
   "mashing potatoes with egg yolk", "A LITTLE STIFFER")

ch("Building it")
sc("""Heat your oven to four hundred. Now here's how to put the potatoes on without them sinking. Don't dump them in the middle and spread. Drop big spoonfuls all around the edges first, then fill in the middle, then gently spread them together with the back of a spoon. Seal them right up to the edges of the dish, so the gravy can't bubble up over the top.""",
   "spooning mashed potatoes around edges of dish", "EDGES FIRST")
sc("""And put the dish on a baking sheet before it goes in the oven, honey. Shepherd's pie loves to bubble over, and burnt gravy on the bottom of your oven smokes up the whole house. Ask me how I know. Harold once called the fire department over a shepherd's pie in nineteen seventy-six. The firemen stayed for supper.""",
   "baking dish on sheet pan going in oven", "THE FIREMEN STAYED")

ch("The secret")
sc("""Now the secret I promised you, and mistake number five, a flat, pale top. Take a plain dinner fork and drag it across the potatoes in lines, all the way across, back and forth, then the other way, like a plowed field. Make lots of little ridges and peaks. Brush the top with a little melted butter. In the oven, every one of those ridges turns brown and crispy, like a potato chip.""",
   "fork making ridges on mashed potato top", "LIKE A PLOWED FIELD")
sc("""Bake for twenty-five minutes, until the filling bubbles around the edges and the ridges are golden. If you want them darker, turn on the broiler for the last two minutes and watch it like a hawk. Then, and this is hard, let it rest for ten minutes before you cut it. It firms up, and you get a clean square instead of a mess. Those corners, honey. Those crispy corners.""",
   "golden shepherd's pie fresh from oven", "THE CRISPY CORNERS")

ch("Making it your own")
sc("""Once you know how, change it any way you like. A layer of corn under the potatoes, which is how they make it in Quebec and call it pâté chinois. Sweet potatoes on top instead of white. Cheddar mixed into the mash. A splash of red wine in the gravy. Or use up leftover Thanksgiving turkey, gravy and mashed potatoes, the day after. That's my favorite of all.""",
   "turkey shepherd's pie with sweet potato top", "MAKE IT YOUR OWN")
sc("""It freezes beautifully, too, sweetheart. Make two, bake one, and freeze the other before baking, wrapped tight in foil. On a busy night, put it straight from the freezer into a three hundred seventy-five degree oven for an hour and fifteen minutes, with the foil on for the first hour. Supper's ready, and you didn't lift a finger.""",
   "foil wrapped casserole in freezer", "MAKE TWO, FREEZE ONE")

sc("""Serve it with something green and sharp on the side, sweetheart, to cut the richness. A simple salad with vinegar dressing, or pickled beets, or a little bowl of chow-chow relish, which is what we had in Ohio. And a big glass of cold milk for the children. My father liked a bottle of ketchup on the table, and my mother pretended not to see it.""",
   "shepherd's pie with pickled beets and salad", "SOMETHING SHARP ON THE SIDE")
ch("Grandma's kitchen")
sc("""So one more time. Russet potatoes, not red. Brown the meat and drain the fat. Don't skip the flour, and cook the filling until it's thick like stew. Let it cool before the potatoes go on. Make them a little stiff, with an egg yolk. Edges first. And plow the top with a fork and brush it with butter. That's my mother's Monday supper, and it's the best thing that ever happened to leftovers.""",
   "shepherd's pie on family table", "THE BEST LEFTOVERS")
sc("""Tell me in the comments, sweetheart. Beef or lamb in your shepherd's pie? And do you fight over the corners too? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "kitchen table evening warm light", "BEEF OR LAMB?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma95", "Shepherd's Pie EVERYONE's Grandma Made (Why Yours Is SOUPY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Shepherd's pie (lamb) and cottage pie (beef) originated in 18th-19th century Britain and Ireland as a way to use leftover roast meat.",
      "Recipe as written by Grandma Ruth: 1 1/2 lb ground beef or lamb, onion, 2 carrots, 2 celery, garlic, 2 tbsp tomato paste, 2 tbsp flour, 1 cup broth, 1 tbsp Worcestershire, thyme, 1 cup peas; 2 1/2 lb russet potatoes, 4 tbsp butter, 1/2 cup milk, 1 egg yolk; 400F for 25 minutes."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
